// Tabel utama (header) tempat tabel baris/anak berada: POR1 -> OPOR, CIN12 -> OCIN, CRD1 -> OCRD. Tabel O... = dirinya sendiri.
export function mainTable(t) {
  if (/^O/.test(t) && SAP_TABLES[t]) return t;
  // tabel arsip/history (A...): ACRD -> OCRD; selain itu tidak ditebak (ACR1 bukan anak OACR)
  if (/^A/.test(t) && /history|log/i.test(tableName(t) || "")) return /^A[A-Z]{3}$/.test(t) && SAP_TABLES["O" + t.slice(1)] ? "O" + t.slice(1) : null;
  const m = /^([A-Z]{3})\d+$/.exec(t);
  return m && SAP_TABLES["O" + m[1]] ? "O" + m[1] : null;
}
export const tableName = t => SAP_TABLES[t] ? SAP_TABLES[t][0] : null;
export const tableModule = t => SAP_TABLES[t] ? SAP_MODULES[SAP_TABLES[t][1]] : null;
